-- Exact normal CLI filename generated by main at 2026-10-12 07:05:15.
-- Source264 Event body is the owning predecessor. Main must first seal the
-- disjoint normal63248 source265 prefix, then append this forward source266.
-- No historical source rewrite, new grants, canary rewrite or auth change.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
SET LOCAL search_path=pg_catalog,public,extensions;
LOCK TABLE public.custodial_release_authority_restore_inventory IN ACCESS EXCLUSIVE MODE;
CREATE TEMP TABLE event_service_date_inventory_before ON COMMIT DROP AS
 SELECT * FROM public.custodial_release_authority_restore_inventory;
CREATE TEMP TABLE event_service_date_function_before ON COMMIT DROP AS
 SELECT oid,proowner,proacl,proconfig,prolang,provolatile,proparallel,prosecdef,prorettype,prosrc,
  pg_get_functiondef(oid) AS definition FROM pg_proc
 WHERE oid='public.mz_mark_employee_event_opened(uuid,text)'::regprocedure;
CREATE TEMP TABLE event_service_date_canary_before ON COMMIT DROP AS
 SELECT oid,proowner,proacl,proconfig,prolang,provolatile,proparallel,prosecdef,prorettype,
  pg_get_functiondef(oid) AS definition FROM pg_proc
 WHERE oid='public.custodial_release_canary_authority_surface()'::regprocedure;

DO $date_binding$
DECLARE target regprocedure:='public.mz_mark_employee_event_opened(uuid,text)'::regprocedure;
 before text;body text;after_body text;after text;
 event_guard constant text:=$event_guard$ if e.id is distinct from original.event_id or e.revision is distinct from original.event_revision
$event_guard$;
 corrected_event_guard constant text:=$corrected_event_guard$ if e.id is distinct from original.event_id or e.revision is distinct from original.event_revision
  or e.event_date is distinct from original.service_date
$corrected_event_guard$;
 reminder_guard constant text:=$reminder_guard$    where s.reminder_date=original.service_date and s.scheduled_for=original.scheduled_for)<>1
$reminder_guard$;
 corrected_reminder_guard constant text:=$corrected_reminder_guard$    where s.scheduled_for=original.scheduled_for)<>1
$corrected_reminder_guard$;
BEGIN
 SELECT definition,prosrc INTO STRICT before,body FROM event_service_date_function_before;
 IF public.static_weekly_digest_text(body)<>'bf09cee0f6a9547c913a438149340993e70bbae1a83b68d4bd0042a76ac1fbe6'
  OR octet_length(convert_to(body,'UTF8'))<>4876
  OR (length(body)-length(replace(body,event_guard,'')))/length(event_guard)<>1
  OR (length(body)-length(replace(body,reminder_guard,'')))/length(reminder_guard)<>1
  OR (length(before)-length(replace(before,body,'')))/length(body)<>1
  OR EXISTS(SELECT 1 FROM event_service_date_inventory_before
    WHERE definition_sha256 IS DISTINCT FROM public.static_weekly_digest_text(definition_sql))
  OR (SELECT count(*) FROM event_service_date_inventory_before WHERE object_kind='function'
    AND object_identity LIKE '%(%' AND to_regprocedure(object_identity)=target
    AND definition_sql=before AND definition_sha256=public.static_weekly_digest_text(before))<>1
  OR (SELECT count(*) FROM event_service_date_inventory_before WHERE object_kind='grant'
    AND object_identity LIKE '%(%' AND to_regprocedure(object_identity)=target
    AND definition_sql=public.custodial_release_authority_current_grant_definition(object_identity))<>1
  OR (SELECT count(*) FROM public.custodial_release_canary_authority_surface()
    WHERE object_kind IN('function','grant') AND object_identity LIKE '%(%'
     AND to_regprocedure(object_identity)=target)<>2
  OR EXISTS(SELECT 1 FROM event_service_date_function_before p
    WHERE p.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog, public']
     OR p.prolang<>(SELECT oid FROM pg_language WHERE lanname='plpgsql') OR p.provolatile<>'v'
     OR p.proparallel<>'u' OR p.prosecdef IS NOT TRUE OR p.prorettype<>'public.event_push_instances'::regtype)
  OR NOT has_function_privilege('service_role',target,'EXECUTE')
  OR EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
    LEFT JOIN pg_roles r ON r.oid=a.grantee WHERE p.oid=target AND a.grantee<>p.proowner
     AND (r.rolname IS NULL OR r.rolname NOT IN('postgres','service_role')
      OR a.is_grantable OR a.privilege_type<>'EXECUTE'))
  OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
    AND tgname='trg_custodial_release_authority_restore_inventory_immutable' AND tgenabled='A')
 THEN RAISE EXCEPTION 'Event service date exact264 predecessor/source/ACL/recovery changed';END IF;
 -- Only calendar binding changes. Keep original recipient, provider receipt,
 -- clock, locks, immutable instance, schedule kind and exact instant fences.
 after_body:=replace(replace(body,event_guard,corrected_event_guard),reminder_guard,corrected_reminder_guard);
 after:=replace(before,body,after_body);EXECUTE after;
 IF pg_get_functiondef(target) IS DISTINCT FROM after
  OR (SELECT prosrc FROM pg_proc WHERE oid=target) IS DISTINCT FROM after_body
  OR EXISTS(SELECT 1 FROM pg_proc p JOIN event_service_date_function_before old ON old.oid=p.oid
    WHERE ROW(p.proowner,p.proacl,p.proconfig,p.prolang,p.provolatile,p.proparallel,p.prosecdef,p.prorettype)
     IS DISTINCT FROM ROW(old.proowner,old.proacl,old.proconfig,old.prolang,old.provolatile,old.proparallel,old.prosecdef,old.prorettype))
 THEN RAISE EXCEPTION 'Event service date unrelated function body/owner/ACL/attributes changed';END IF;
END $date_binding$;

-- Rebind only this already-registered function's exact recovery definition.
-- Do not recapture or modify the intervening source265 canary/other inventory.
ALTER TABLE public.custodial_release_authority_restore_inventory DISABLE TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
DO $recovery$
DECLARE target regprocedure:='public.mz_mark_employee_event_opened(uuid,text)'::regprocedure;
 changed integer;
BEGIN
 UPDATE public.custodial_release_authority_restore_inventory i
  SET definition_sql=pg_get_functiondef(target),
   definition_sha256=public.static_weekly_digest_text(pg_get_functiondef(target)),captured_at=statement_timestamp()
  WHERE i.object_kind='function' AND i.object_identity LIKE '%(%' AND to_regprocedure(i.object_identity)=target
   AND i.definition_sql=(SELECT old.definition_sql FROM event_service_date_inventory_before old WHERE old.inventory_id=i.inventory_id)
   AND i.definition_sha256=public.static_weekly_digest_text(i.definition_sql);
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>1 THEN RAISE EXCEPTION 'Event service date exact original recovery function row changed';END IF;
END $recovery$;
ALTER TABLE public.custodial_release_authority_restore_inventory ENABLE ALWAYS TRIGGER trg_custodial_release_authority_restore_inventory_immutable;
DO $scope$
DECLARE target regprocedure:='public.mz_mark_employee_event_opened(uuid,text)'::regprocedure;
BEGIN
 IF (SELECT count(*) FROM public.custodial_release_authority_restore_inventory)<>(SELECT count(*) FROM event_service_date_inventory_before)
  OR EXISTS(SELECT old.* FROM event_service_date_inventory_before old
    WHERE NOT(old.object_kind='function' AND old.object_identity LIKE '%(%' AND to_regprocedure(old.object_identity)=target)
    EXCEPT SELECT * FROM public.custodial_release_authority_restore_inventory)
  OR EXISTS(SELECT now_row.* FROM public.custodial_release_authority_restore_inventory now_row
    WHERE NOT(now_row.object_kind='function' AND now_row.object_identity LIKE '%(%' AND to_regprocedure(now_row.object_identity)=target)
    EXCEPT SELECT * FROM event_service_date_inventory_before)
  OR EXISTS(SELECT 1 FROM pg_proc p JOIN event_service_date_canary_before old ON old.oid=p.oid
    WHERE pg_get_functiondef(p.oid) IS DISTINCT FROM old.definition
     OR ROW(p.proowner,p.proacl,p.proconfig,p.prolang,p.provolatile,p.proparallel,p.prosecdef,p.prorettype)
      IS DISTINCT FROM ROW(old.proowner,old.proacl,old.proconfig,old.prolang,old.provolatile,old.proparallel,old.prosecdef,old.prorettype))
  OR EXISTS(SELECT 1 FROM public.custodial_release_authority_restore_inventory i
    WHERE i.definition_sha256 IS DISTINCT FROM public.static_weekly_digest_text(i.definition_sql))
  OR (SELECT count(*) FROM public.custodial_release_authority_restore_inventory i
    WHERE i.object_kind='function' AND i.object_identity LIKE '%(%' AND to_regprocedure(i.object_identity)=target
     AND i.definition_sql=pg_get_functiondef(target))<>1
  OR (SELECT count(*) FROM public.custodial_release_authority_restore_inventory i
    WHERE i.object_kind='grant' AND i.object_identity LIKE '%(%' AND to_regprocedure(i.object_identity)=target
     AND i.definition_sql=public.custodial_release_authority_current_grant_definition(i.object_identity))<>1
  OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.custodial_release_authority_restore_inventory'::regclass
    AND tgname='trg_custodial_release_authority_restore_inventory_immutable' AND tgenabled='A')
 THEN RAISE EXCEPTION 'Event service date unrelated inventory/canary/grant or ALWAYS guard changed';END IF;
END $scope$;
COMMIT;
